customCSS:
/* d-BMO: prata espelhada, vidro e o rosto do firmware. Os marcadores em maiúsculas são preenchidos por gerar_tema_desktop.py. */
:root {
  /* Só a superfície do chat fica transparente para o espelho aparecer; janelas, menus e cartões continuam opacos. */
  --ui-chat-surface-background: transparent;
  /* Todo texto em preto sólido: cinza sobre o espelho prata fica ilegível. */
  --ui-text-primary: #090A0C;
  --ui-text-secondary: #090A0C;
  --ui-text-tertiary: #090A0C;
  --ui-text-quaternary: #090A0C;
  --dbmo-glass: rgb(255 255 255 / 0.3);
  --dbmo-glass-strong: rgb(255 255 255 / 0.5);
  --dbmo-glass-edge: inset 0 0 0 1px rgb(255 255 255 / 0.6), inset 0 1px 0 rgb(255 255 255 / 0.85), inset 0 -1px 0 rgb(36 39 43 / 0.1);
  --dbmo-glass-drop: 0 2px 10px rgb(36 39 43 / 0.14);
  --dbmo-blur: blur(14px) saturate(160%);
}

/* Espelho: faixas largas e claras de luz sobre prata, só no contêiner principal da janela. */
.w-screen.bg-\(--ui-bg-chrome\) {
  background:
    linear-gradient(180deg, rgb(255 255 255 / 0.45), rgb(255 255 255 / 0) 30%),
    linear-gradient(115deg, #F4F5F6 0%, #DCDFE2 18%, #F7F8F9 34%, #E2E5E8 52%, #D5D9DC 68%, #EEF0F1 84%, #DEE1E4 100%);
}

/* Texto pequeno em vermelho: tom mais fundo do mesmo vermelho, para ler bem sobre a prata. */
.text-\(--theme-primary\), .text-\(--ui-accent\) { color: #A51B27; }

/* Vidro. */
[data-slot="button"]:is([data-variant="secondary"], [data-variant="outline"], [data-variant="chip"], [data-variant="floating"]),
[data-slot="composer-surface"] {
  background-color: var(--dbmo-glass);
  -webkit-backdrop-filter: var(--dbmo-blur);
  backdrop-filter: var(--dbmo-blur);
  box-shadow: var(--dbmo-glass-edge), var(--dbmo-glass-drop);
}
[data-slot="button"][data-variant="default"] {
  background: linear-gradient(180deg, rgb(255 255 255 / 0.3), rgb(255 255 255 / 0) 55%), rgb(217 35 50 / 0.88);
  color: #fff;
  -webkit-backdrop-filter: var(--dbmo-blur);
  backdrop-filter: var(--dbmo-blur);
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.28), inset 0 1px 0 rgb(255 255 255 / 0.5), 0 4px 14px rgb(217 35 50 / 0.3);
}
[data-slot="button"] {
  border-radius: 6px;
  transition-property: background-color, box-shadow, color, transform;
  transition-duration: 150ms;
  transition-timing-function: ease;
}
[data-slot="button"]:active:not(:disabled) {
  transform: scale(0.97);
  transition-duration: 120ms;
  transition-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
}
[data-slot="sidebar-menu-button"][data-active="true"] {
  background-color: var(--dbmo-glass-strong);
  box-shadow: var(--dbmo-glass-edge);
}
@media (hover: hover) and (pointer: fine) {
  [data-slot="button"]:is([data-variant="ghost"], [data-variant="secondary"], [data-variant="outline"], [data-variant="chip"]):hover,
  [data-slot="sidebar-menu-button"]:hover {
    background-color: var(--dbmo-glass-strong);
    box-shadow: var(--dbmo-glass-edge), var(--dbmo-glass-drop);
  }
  [data-slot="button"][data-variant="default"]:hover {
    background-color: rgb(217 35 50 / 0.96);
  }
}

